export function applyCriterionRelevanceV22(request:TripRequest,intent:V8IntentProfile,items:V8Ranked[],profiles:Map<string,DestinationChoiceProfileV22>):{ranked:V8Ranked[];audit:CriterionRelevanceAuditV22}{
